import{_ as e,o as i,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2016-MAR-02 -- Ceph Developer Monthly","description":"","frontmatter":{"title":"2016-MAR-02 -- Ceph Developer Monthly","date":"2016-03-03T00:00:00.000Z","updated":"2016-03-04T00:00:00.000Z","tags":["Ceph","开发者月度会议","网络加密","同步消息协议","发布流程","Paddle 和 Pulpito","Lua 支持","Ceph Jel"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2016/2016-MAR-02_-_-_Ceph_Developer_Monthly.md","filePath":"posts/2016/2016-MAR-02_-_-_Ceph_Developer_Monthly.md","lastUpdated":1780459816000}'),o={name:"posts/2016/2016-MAR-02_-_-_Ceph_Developer_Monthly.md"};function p(r,l,n,s,_,h){return i(),t("div",null,[...l[0]||(l[0]=[a('<h3 id="改进后的中文总结" tabindex="-1">改进后的中文总结 <a class="header-anchor" href="#改进后的中文总结" aria-label="Permalink to &quot;改进后的中文总结&quot;">​</a></h3><p>在 2023 年 11 月举行的 Ceph 开发者月度会议（APAC 版）中，多位 Ceph 开发者参与了讨论，包括 Sage、Marcus、Patrick、Noah 等。会议主要围绕以下议题展开：</p><p><strong>1. 网络加密</strong>：</p><ul><li>讨论了为 Ceph 添加网络加密的需求，特别是在当前的政治气候下。</li><li>提出通过扩展当前的消息协议来实现加密，并使用现有的会话密钥进行加密。</li><li>讨论了加密对消息吞吐量的影响，以及如何利用处理器加速功能来提高加密效率。</li><li>建议将该功能添加到 Google 夏季代码项目中。</li></ul><p><strong>2. 同步消息协议</strong>：</p><ul><li>介绍了新的同步消息协议设计，主要支持在后台处理消息。</li><li>讨论了该设计如何与 DPDK 和 liburing 等库集成，以实现高性能网络通信。</li><li>讨论了多 OSD 宿主机环境下的性能优化问题，以及如何避免锁竞争。</li><li>讨论了与现有异步消息协议的兼容性，以及如何逐步迁移。</li></ul><p><strong>3. 发布开发支持版本</strong>：</p><ul><li>讨论了发布开发支持版本的流程，以及如何简化发布过程。</li><li>讨论了使用 Jenkins 构建 Ceph 软件包的可行性，以及如何与现有的 Git 构建器兼容。</li></ul><p><strong>4. Paddle 和 Pulpito</strong>：</p><ul><li>讨论了为 Paddle 添加问题和评论字段的需求，以方便跟踪测试结果。</li><li>讨论了为 Pulpito 添加新的查询功能，以支持对特定 SHA 和作业描述的查询。</li></ul><p><strong>5. Lua 支持</strong>：</p><ul><li>讨论了为 Ceph OSD 添加 Lua 支持的需求，以及如何确保安全性。</li><li>讨论了使用白名单机制来限制 Lua 类的加载，以及如何将 Lua 库打包成独立的软件包。</li></ul><p><strong>6. 其他事项</strong>：</p><ul><li>讨论了 Ceph Jel 的状态，以及即将到来的 RC 版本。</li><li>介绍了 Ceph Hackathon 的相关信息，包括时间、地点和主题。</li></ul><p>会议制定了后续行动计划，包括 Sage 收集 Ceph Hackathon 的主题建议，Marcus 将同步消息协议的幻灯片发送给 Adam 和 Casey，其他开发者将继续推进各自的开发工作。</p><h3 id="标签" tabindex="-1">标签 <a class="header-anchor" href="#标签" aria-label="Permalink to &quot;标签&quot;">​</a></h3><ul><li>Ceph</li><li>开发者月度会议</li><li>网络加密</li><li>同步消息协议</li><li>发布流程</li><li>Paddle 和 Pulpito</li><li>Lua 支持</li></ul>',17)])])}const c=e(o,[["render",p]]);export{d as __pageData,c as default};
